BEGIN;
CREATE OR REPLACE FUNCTION professional.owned_profile_publication_readiness(p_owner_party_id uuid) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,public,core,membership,evidence,professional AS $$
WITH profile AS(SELECT * FROM professional.professional_profiles WHERE party_id=p_owner_party_id),facts AS(
 SELECT EXISTS(SELECT 1 FROM profile) profile_exists,
  EXISTS(SELECT 1 FROM profile WHERE current_job_title_ar IS NOT NULL) has_title,
  EXISTS(SELECT 1 FROM profile WHERE total_professional_experience_years IS NOT NULL) has_years,
  EXISTS(SELECT 1 FROM membership.memberships m WHERE m.party_id=p_owner_party_id AND m.status_code='ACTIVE' AND (m.valid_from IS NULL OR m.valid_from<=current_date) AND (m.valid_to IS NULL OR m.valid_to>=current_date)) active_membership,
  EXISTS(SELECT 1 FROM professional.professional_fingerprints f JOIN profile p USING(professional_profile_id) WHERE f.status_code IN('ACTIVE','UPDATE_REQUIRED')) has_fingerprint,
  EXISTS(SELECT 1 FROM evidence.evidence_links l JOIN evidence.evidence_items e ON e.evidence_item_id=l.evidence_item_id JOIN evidence.evidence_files ef ON ef.evidence_item_id=e.evidence_item_id JOIN core.files fi ON fi.file_id=ef.file_id WHERE e.owner_party_id=p_owner_party_id AND l.target_entity_type IN('ACADEMIC_QUALIFICATION','EMPLOYMENT_EXPERIENCE','PROJECT_EXPERIENCE','CONSULTING_EXPERIENCE','TRAINING_EXPERIENCE','RESEARCH_EXPERIENCE','PROFESSIONAL_FINGERPRINT') AND fi.scan_status_code='SAFE' AND fi.archived_at IS NULL) has_safe_evidence,
  EXISTS(SELECT 1 FROM evidence.evidence_links l JOIN evidence.evidence_items e ON e.evidence_item_id=l.evidence_item_id WHERE e.owner_party_id=p_owner_party_id AND e.status_code='VERIFIED' AND l.target_entity_type IN('ACADEMIC_QUALIFICATION','EMPLOYMENT_EXPERIENCE','PROJECT_EXPERIENCE','CONSULTING_EXPERIENCE','TRAINING_EXPERIENCE','RESEARCH_EXPERIENCE','PROFESSIONAL_FINGERPRINT')) has_verified_evidence,
  EXISTS(SELECT 1 FROM professional.fingerprint_contexts c JOIN professional.professional_fingerprints f USING(professional_fingerprint_id) JOIN profile p USING(professional_profile_id)) has_context,
  EXISTS(SELECT 1 FROM professional.fingerprint_strength_assessments a JOIN professional.professional_fingerprints f USING(professional_fingerprint_id) JOIN profile p USING(professional_profile_id) WHERE a.is_current) has_strength
),scored AS(SELECT *,((has_title::int*15)+(has_years::int*10)+(active_membership::int*10)+(has_fingerprint::int*20)+(has_safe_evidence::int*15)+(has_verified_evidence::int*15)+(has_context::int*10)+(has_strength::int*5)) score FROM facts)
SELECT jsonb_build_object('ready',profile_exists AND has_title AND has_years AND active_membership AND has_fingerprint AND has_safe_evidence AND score>=80,'score',score,'minimumScore',80,
 'checks',jsonb_build_array(
 jsonb_build_object('code','PROFILE_TITLE','passed',has_title,'weight',15,'required',true),jsonb_build_object('code','EXPERIENCE_YEARS','passed',has_years,'weight',10,'required',true),jsonb_build_object('code','ACTIVE_MEMBERSHIP','passed',active_membership,'weight',10,'required',true),jsonb_build_object('code','PROFESSIONAL_FINGERPRINT','passed',has_fingerprint,'weight',20,'required',true),jsonb_build_object('code','SAFE_LINKED_EVIDENCE','passed',has_safe_evidence,'weight',15,'required',true),jsonb_build_object('code','VERIFIED_EVIDENCE','passed',has_verified_evidence,'weight',15,'required',false),jsonb_build_object('code','FINGERPRINT_CONTEXT','passed',has_context,'weight',10,'required',false),jsonb_build_object('code','FINGERPRINT_STRENGTH','passed',has_strength,'weight',5,'required',false)),
 'missing',coalesce((SELECT jsonb_agg(x->>'code') FROM jsonb_array_elements(jsonb_build_array(jsonb_build_object('code','PROFILE_TITLE','passed',has_title),jsonb_build_object('code','EXPERIENCE_YEARS','passed',has_years),jsonb_build_object('code','ACTIVE_MEMBERSHIP','passed',active_membership),jsonb_build_object('code','PROFESSIONAL_FINGERPRINT','passed',has_fingerprint),jsonb_build_object('code','SAFE_LINKED_EVIDENCE','passed',has_safe_evidence),jsonb_build_object('code','VERIFIED_EVIDENCE','passed',has_verified_evidence),jsonb_build_object('code','FINGERPRINT_CONTEXT','passed',has_context),jsonb_build_object('code','FINGERPRINT_STRENGTH','passed',has_strength))) x WHERE NOT (x->>'passed')::boolean),'[]'::jsonb)) FROM scored;
$$;
CREATE OR REPLACE FUNCTION professional.enforce_profile_publication_readiness() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,professional AS $$
DECLARE v jsonb;BEGIN v:=professional.owned_profile_publication_readiness(NEW.requested_by_party_id);IF NOT coalesce((v->>'ready')::boolean,false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Profile publication readiness requirements are not met',DETAIL=v::text;END IF;RETURN NEW;END;$$;
CREATE TRIGGER trg_profile_publication_readiness BEFORE INSERT ON professional.profile_publication_requests FOR EACH ROW EXECUTE FUNCTION professional.enforce_profile_publication_readiness();
INSERT INTO integration.schema_migrations(migration_name) VALUES('0750_v113_backend_publication_readiness') ON CONFLICT DO NOTHING;COMMIT;
